  (('c3000000-0000-4000-a000-' || lpad('98'::text, 12, '0'))::uuid, ('b3000000-0000-4000-a000-' || lpad('98'::text, 12, '0'))::uuid, 'Steak Studio', 'elite', 'active', true, NOW() + INTERVAL '30 days', 'BBS Mall', 'shops.lively.mall', 'BBS Mall', '1st Floor', 'T' || '-' || lpad(18::text, 2, '0'), 'services · Westlands', '+25470' || lpad(2000098::text, 7, '0'), 'elite.seed' || lpad(98::text, 3, '0') || '@maanta.app', '+25470' || lpad(2000098::text, 7, '0'), 2100.00, 0, true, false, NOW() - (8 || ' days')::interval, 0.86),
  (('c3000000-0000-4000-a000-' || lpad('99'::text, 12, '0'))::uuid, ('b3000000-0000-4000-a000-' || lpad('99'::text, 12, '0'))::uuid, 'Accessories Avenue', 'elite', 'active', true, NOW() + INTERVAL '30 days', 'BBS Mall', 'shops.lively.mall', 'BBS Mall', '2nd Floor', 'U' || '-' || lpad(19::text, 2, '0'), 'restaurant · CBD', '+25470' || lpad(2000099::text, 7, '0'), 'elite.seed' || lpad(99::text, 3, '0') || '@maanta.app', '+25470' || lpad(2000099::text, 7, '0'), 2200.00, 0, true, false, NOW() - (9 || ' days')::interval, 0.87),
  (('c3000000-0000-4000-a000-' || lpad('100'::text, 12, '0'))::uuid, ('b3000000-0000-4000-a000-' || lpad('100'::text, 12, '0'))::uuid, 'Drone Den', 'elite', 'active', true, NOW() + INTERVAL '30 days', 'BBS Mall', 'shops.lively.mall', 'BBS Mall', 'Food Court', 'V' || '-' || lpad(20::text, 2, '0'), 'grocery · Eastleigh', '+25470' || lpad(2000100::text, 7, '0'), 'elite.seed' || lpad(100::text, 3, '0') || '@maanta.app', '+25470' || lpad(2000100::text, 7, '0'), 2300.00, 0, true, false, NOW() - (10 || ' days')::interval, 0.88)
) AS v(id, user_id, merchant_name, tier, status, elite_trial_active, trial_ends_at,
  node, what3words_address, mall_name, floor, unit_number, entrance_notes,
  phone, email, whatsapp, account_balance, outstanding_arrears,
  is_visible, is_shadow_banned, onboarded_at, trust_metric)
WHERE NOT EXISTS (SELECT 1 FROM public.merchants m WHERE m.id = v.id);

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'merchants' AND column_name = 'lat'
  ) THEN
    UPDATE public.merchants m
    SET lat = -1.2746 + ((n % 10) - 5) * 0.0002,
        lng = 36.8501 + ((n % 7) - 3) * 0.00025,
        updated_at = NOW()
    FROM generate_series(1, 100) AS n
    WHERE m.id = ('c3000000-0000-4000-a000-' || lpad(n::text, 12, '0'))::uuid;
  END IF;
END $$;

INSERT INTO public.deals (
  id, merchant_id, node, title, description, image_url,
  discount_type, discount_value, deal_type, flash_duration_hours,
  is_active, boost_active, max_claims, claims_count, starts_at,
  price_kes, compare_at_kes, charges, expires_at
)
SELECT
  ('d3000000-0000-4000-a000-' || lpad(deal_n::text, 12, '0'))::uuid,
  ('c3000000-0000-4000-a000-' || lpad(n::text, 12, '0'))::uuid,
  'BBS Mall',
  CASE WHEN deal_n % 2 = 1 THEN 'FLASH: ' || names[n] || ' today special'
       ELSE names[n] || ' — member offer' END,
  'Synthetic elite deal for rehearsal — show your Maanta code at the counter.',
  images[1 + ((n - 1) % array_length(images, 1))],
  'fixed', 200, CASE WHEN deal_n % 2 = 1 THEN 'flash' ELSE 'standard' END,
  6, true, false, CASE WHEN deal_n % 2 = 1 THEN 15 ELSE 30 END, 0,
  NOW() - INTERVAL '2 hours',
  (400 + (n % 20) * 50)::numeric,
  (800 + (n % 20) * 80)::numeric,
  '[]'::jsonb,
  CASE WHEN deal_n % 2 = 1 THEN NOW() + INTERVAL '6 hours'
       ELSE NOW() + INTERVAL '14 days' END
FROM generate_series(1, 100) AS n,
     generate_series(n * 2 - 1, n * 2) AS deal_n,
     (SELECT ARRAY['Nairobi Fresh Market', 'Globe Grill', 'Elite Fashion Hub', 'Westlands Coffee Co', 'CBD Electronics Plus', 'Karen Pharmacy', 'Kilimani Bistro', 'Eastleigh Spice House', 'BBS Mall Gourmet', 'Savanna Style', 'Urban Threads', 'Golden Plate Kitchen', 'Metro Gadgets', 'Bloom Beauty', 'Harbor Café', 'Prime Grocers', 'Silk & Stitch', 'Sunrise Bakery', 'TechNest Mobile', 'Wellness Corner', 'Maasai Grill', 'Palm Court Dining', 'Velvet Boutique', 'Green Basket', 'Circuit City Hub', 'Radiant Salon', 'Mocha Lane', 'Heritage Foods', 'TrendSetters', 'Cloud Nine Café', 'SmartHome Store', 'CarePlus Pharmacy', 'Flame & Fork', 'Organic Oasis', 'Luxe Apparel', 'Byte Bazaar', 'Serene Spa', 'Corner Deli', 'Fashion Forward', 'Power Tools Pro', 'Sweet Crust', 'Urban Pantry', 'Designer Den', 'Digital Depot', 'FreshCuts Barbers', 'Harvest Table', 'Elite Sneakers', 'Gadget Galaxy', 'Tea & Tales', 'Market Square Eats', 'Chic Collective', 'Home Essentials', 'QuickFix Services', 'Artisan Roast', 'Style Studio', 'Value Mart', 'Phone Doctor', 'Garden Plate', 'Runway Retail', 'Connect Hub', 'Pastry Palace', 'Neighborhood Nosh', 'Tailor Made', 'Screen Savers', 'Juice Junction', 'Mall Food Court Star', 'Premium Fabrics', 'Tech Traders', 'Glow Beauty Bar', 'Daily Bread Co', 'Sport Elite', 'Audio Avenue', 'Noodle House', 'Fresh Fare', 'Urban Outfitters KE', 'Repair Right', 'Cocoa Corner', 'Family Feast', 'Denim District', 'Camera Corner', 'Smoothie Spot', 'Grill Masters', 'Boutique 254', 'Laptop Lounge', 'Spice Route', 'Healthy Bites', 'Formal Wear Co', 'Gaming Gear', 'Cupcake Cove', 'Street Eats', 'Shoe Sanctuary', 'Watch World', 'Ramen Republic', 'Organic Select', 'Kids Fashion Hub', 'Printer Pro', 'Bubble Tea Bar', 'Steak Studio', 'Accessories Avenue', 'Drone Den', 'Sushi Social', 'Bulk Buy Mart', 'Luxury Linens', 'VR Ventures']::text[] AS names) AS t,
     (SELECT ARRAY['/deals/food-01.svg', '/deals/grocery-01.svg', '/deals/fashion-01.svg', '/deals/services-01.svg', '/deals/food-02.svg', '/deals/grocery-02.svg', '/deals/services-01.svg']::text[] AS images) AS img
WHERE NOT EXISTS (
  SELECT 1 FROM public.deals d
  WHERE d.id = ('d3000000-0000-4000-a000-' || lpad(deal_n::text, 12, '0'))::uuid
);

COMMIT;

SELECT count(*) AS elite_merchants FROM merchants WHERE id::text LIKE 'c3000000-%';
SELECT count(*) AS elite_deals FROM deals WHERE id::text LIKE 'd3000000-%';
